div.t-att-class:
{
                                     'active': this.state.step === st.number,
                                     'completed': this.state.step > st.number,
                                     'clickable': this.canGoToStep(st.number) and this.state.step !== st.number,
                                     'disabled': !this.canGoToStep(st.number) and this.state.step !== st.number
                                 }
